import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Properties;

public class Job {
    interface SumFn {
        default long apply(List<Long> inputs) {
            return inputs.stream().mapToLong(Long::longValue).sum();
        }
        long merge(List<Long> partials);
    }
    static final class ExactSum implements SumFn {
        public long merge(List<Long> partials) {
            return partials.stream().mapToLong(Long::longValue).sum();
        }
    }
    static final class LegacySum implements SumFn {
        public long merge(List<Long> partials) {
            return partials.stream().mapToLong(Long::longValue).max().orElse(0);
        }
    }
    static SumFn selected(Properties config) {
        return switch (config.getProperty("aggregate")) {
            case "exact" -> new ExactSum();
            case "legacy" -> new LegacySum();
            default -> throw new IllegalArgumentException("Unknown aggregate");
        };
    }
    static long run(SumFn fn, List<List<Long>> partitions) {
        return fn.merge(partitions.stream().map(fn::apply).toList());
    }
    public static void main(String[] args) throws Exception {
        Properties config = new Properties();
        try (Reader input = Files.newBufferedReader(Path.of(args[0]))) {
            config.load(input);
        }
        System.out.println(run(selected(config), List.of(List.of(2L), List.of(3L))));
    }
}

